-- Stub of the live schema (columns, keys, uniques, FKs) for the tables the save touches.
-- Pulled from information_schema on 2026-11-10. Defaults are NOT copied (tests supply values).
create extension if not exists pgcrypto;
create table bestiary (id uuid default gen_random_uuid(), name text not null, slug text, primary key (id));
create table campaign_runs (id uuid default gen_random_uuid(), campaign_id text not null, run_number integer not null, status text not null, started_at timestamp with time zone, ended_at timestamp with time zone, created_at timestamp with time zone not null default now(), game_context text not null default 'x', primary key (id));
create table character_faith (id uuid default gen_random_uuid(), character_id uuid not null, deity_slug text not null, primary key (id));
create table character_known_effects (character_id uuid not null, item_slug text not null, column_index smallint not null, primary key (character_id,item_slug,column_index));
create table character_known_recipes (character_id uuid not null, recipe_slug text not null, journal_id uuid, primary key (character_id,recipe_slug));
create table character_known_runes (character_id uuid not null, school text not null, primary key (character_id,school));
create table character_known_weaknesses (character_id uuid not null, bestiary_slug text not null, detail text not null, journal_id uuid, primary key (character_id,bestiary_slug,detail));
create table character_relationships (id uuid default gen_random_uuid(), subject_id uuid not null, object_id uuid not null, trust integer not null default 0, primary key (id));
create table characters (id uuid default gen_random_uuid(), name text not null, level integer not null default 1, class text not null default 'x', xp integer, xp_to_next integer, avatar_image_url text, portrait_image_url text, hp_current integer, hp_max integer, ac integer, initiative integer, proficiency_bonus integer, passive_perception integer, str_score integer, str_modifier integer, dex_score integer, dex_modifier integer, con_score integer, con_modifier integer, int_score integer, int_modifier integer, wis_score integer, wis_modifier integer, cha_score integer, cha_modifier integer, weight_current numeric, weight_max numeric, is_player boolean, created_at timestamp with time zone, updated_at timestamp with time zone, conditions jsonb, character_type text not null default 'player', speed text, senses text, skills text, size text, cr text, languages text, damage_resistances text, damage_immunities text, condition_immunities text, sheet_species text, sheet_background text, sheet_alignment text, sheet_player_name text, sheet_hp_temp integer, sheet_hit_dice text, sheet_heroic_inspiration boolean, sheet_passive_insight integer, sheet_passive_investigation integer, sheet_save_proficiencies jsonb, sheet_skill_proficiencies jsonb, sheet_defenses text, sheet_proficiencies jsonb, sheet_features jsonb, sheet_attacks jsonb, sheet_currency jsonb, sheet_appearance jsonb, sheet_personality jsonb, sheet_backstory text, sheet_allies_organizations text, sheet_additional_notes text, sheet_spellcasting jsonb, in_party boolean not null default true, idle_url text, talking_url text, archived_at timestamp with time zone, voice_id text, voice_description text, seat_id uuid, run_id uuid, locked_at timestamp with time zone, stage_scale numeric not null default 1, stage_offset_y numeric not null default 0, rest_actions_remaining integer not null default 1, unfed_rest_streak integer not null default 0, hit_dice_remaining integer, face_image_url text, hero_image_url text, death_saves jsonb not null default '{}', exhaustion smallint not null default 0, inebriation jsonb, primary key (id));
create table cinematic_clips (id uuid default gen_random_uuid(), location text not null default 'x', primary key (id));
create table cinematic_views (id uuid default gen_random_uuid(), character_id uuid not null, clip_id uuid not null, primary key (id));
create table combat_state (id uuid default gen_random_uuid(), map_id uuid not null, round integer not null default 1, primary key (id));
create table crafting_projects (id uuid default gen_random_uuid(), character_id uuid not null, item_id uuid not null, primary key (id));
create table deities (slug text not null, name text not null, primary key (slug));
create table dialogue (id uuid default gen_random_uuid(), environment_id uuid, speaker text not null, speaker_type text, text text not null, sort_order integer, created_at timestamp with time zone, channel text not null default 'main', run_id uuid, recipient text, primary key (id));
create table environments (id uuid default gen_random_uuid(), name text not null, time_of_day text not null default 'night', background_image_url text, created_at timestamp with time zone, updated_at timestamp with time zone, primary key (id));
create table equipment_items (id uuid default gen_random_uuid(), character_id uuid, slot text not null, name text not null, item_key text, primary key (id));
create table faith_events (id uuid default gen_random_uuid(), character_id uuid not null, deity_slug text not null, kind text not null, primary key (id));
create table game_clock (session_id uuid not null, game_day integer not null, minutes_of_day integer not null, exchanges_since_advance integer not null default 0, advance_threshold integer not null default 5, updated_at timestamp with time zone not null default now(), primary key (session_id));
create table inventory_items (id uuid default gen_random_uuid(), character_id uuid, name text not null, quantity integer, item_id uuid, confiscated_from uuid, item_key text, condition text not null default 'pristine', upgrades jsonb not null default '[]', primary key (id));
create table item_events (id uuid default gen_random_uuid(), inventory_item_id uuid not null, character_id uuid, kind text not null, primary key (id));
create table items (id uuid default gen_random_uuid(), slug text not null, name text not null, primary key (id));
create table journal_entries (id uuid default gen_random_uuid(), character_id uuid not null, session_id uuid, body text not null, primary key (id));
create table journal_offers (id uuid default gen_random_uuid(), character_id uuid not null, body text not null, primary key (id));
create table magical_resources (id uuid default gen_random_uuid(), character_id uuid, resource_type text not null, current_value integer, primary key (id));
create table npc_encounters (id uuid default gen_random_uuid(), character_id uuid, name text not null, portrait_url text, is_active boolean, hp_current integer, hp_max integer, conditions jsonb, face_url text, voice_id text, disposition text, aliases text[] not null default '{}', stage_scale numeric not null default 1, stage_offset_y numeric not null default 0, bestiary_id uuid, primary key (id));
create table npc_knowledge (id uuid default gen_random_uuid(), npc_name text not null, kind text not null, payload jsonb not null default '{}', learned_from_character uuid, learned_at timestamp with time zone not null default now(), primary key (id));
create table party_position (campaign_run_id uuid not null, node_id uuid not null, node_type text not null, arrived_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now(), primary key (campaign_run_id));
create table party_situation (campaign_run_id uuid not null, node_key text not null, place text, area_name text, primary key (campaign_run_id));
create table party_supplies (id uuid default gen_random_uuid(), campaign_id uuid, supplies integer not null, primary key (id));
create table party_vessels (id uuid default gen_random_uuid(), campaign_run_id uuid, kind text not null, primary key (id));
create table player_seats (id uuid default gen_random_uuid(), seat_number integer not null, primary key (id));
create table prayers (id uuid default gen_random_uuid(), session_id uuid, character_id uuid not null, deity_slug text, primary key (id));
create table relationship_events (id uuid default gen_random_uuid(), subject_id uuid not null, object_id uuid not null, kind text not null, primary key (id));
create table rest_events (id uuid default gen_random_uuid(), session_id uuid, rest_type text not null, bard_character_id uuid, primary key (id));
create table roll_attempts (id uuid default gen_random_uuid(), request_id uuid not null, character_id uuid not null, outcome text not null, primary key (id));
create table roll_requests (id uuid default gen_random_uuid(), correlation_id uuid not null default gen_random_uuid(), session_id uuid, character_id uuid not null, status text not null, primary key (id));
create table session_beats (id uuid default gen_random_uuid(), session_id uuid, beat_type text not null, character_id uuid, run_id uuid, primary key (id));
create table session_telemetry (id uuid default gen_random_uuid(), character_id uuid, campaign_id text not null, primary key (id));
create table sessions (id uuid default gen_random_uuid(), campaign_id text, title text, status text not null, started_at timestamp with time zone not null default now(), active_character_id uuid, primary key (id));
create table skill_progress (id uuid default gen_random_uuid(), character_id uuid not null, skill text not null, teacher_id uuid, roll_request_id uuid, primary key (id));
create table story_dialogue (id uuid default gen_random_uuid(), character_id uuid, campaign_id text not null, speaker text not null, primary key (id));
create table subnodal_maps (id uuid default gen_random_uuid(), slug text not null, primary key (id));
create table subnodal_nodes (id uuid default gen_random_uuid(), map_id uuid not null, node_number integer not null, primary key (id));
create table subnodal_party_position (campaign_run_id uuid not null, map_id uuid not null, node_id uuid, primary key (campaign_run_id,map_id));
create table subnodal_visibility (campaign_run_id uuid not null, node_id uuid not null, state text not null, primary key (campaign_run_id,node_id));
create table time_log (id uuid default gen_random_uuid(), session_id uuid not null, event_type text not null, minutes_advanced integer, primary key (id));
create table travel_arrivals (id uuid default gen_random_uuid(), node_id uuid not null, event_id uuid, primary key (id));
create table travel_march (campaign_run_id uuid not null, leader_character_id uuid, primary key (campaign_run_id));
create table travel_node_events (id uuid default gen_random_uuid(), node_id uuid not null, primary key (id));
create table travel_nodes (id uuid default gen_random_uuid(), node_key text not null, name text not null, node_type text not null, discovered_at timestamp with time zone, name_known_at timestamp with time zone, metadata jsonb not null default '{}', primary key (id));
create table vtt_ground_items (id uuid default gen_random_uuid(), map_id uuid not null, item_id uuid not null, name text not null, primary key (id));
create table vtt_maps (id uuid default gen_random_uuid(), name text not null, is_active boolean not null default false, meta jsonb not null default '{}', primary key (id));
create table vtt_tokens (id uuid default gen_random_uuid(), map_id uuid not null, character_id uuid, label text not null, grid_x integer not null, grid_y integer not null, is_visible boolean not null default true, is_hidden boolean not null default false, hp_current integer, hp_max integer, summon jsonb, effects jsonb not null default '[]', primary key (id));
create table walk_events (sig text not null, bucket bigint not null, text text, primary key (sig,bucket));
create table walk_world (campaign_run_id uuid not null, version bigint not null, state jsonb not null, primary key (campaign_run_id));
create table work_details (id uuid default gen_random_uuid(), campaign_run_id uuid not null, day integer not null, primary key (id));
create table world_flags (campaign_id text not null, key text not null, value jsonb not null, set_at timestamp with time zone not null default now(), set_by text, note text, primary key (campaign_id,key));

-- the keys that matter
alter table campaign_runs add unique (campaign_id, run_number);
create unique index one_live_run_per_campaign on campaign_runs (campaign_id) where status <> 'ended';
create unique index npc_one_active on npc_encounters (lower(name), coalesce(character_id,'00000000-0000-0000-0000-000000000000'::uuid)) where is_active;
alter table characters add foreign key (run_id) references campaign_runs(id);
alter table dialogue add foreign key (run_id) references campaign_runs(id);
alter table dialogue add foreign key (environment_id) references environments(id) on delete cascade;
alter table inventory_items add foreign key (character_id) references characters(id) on delete cascade;
alter table inventory_items add foreign key (item_id) references items(id) on delete set null;
alter table item_events add foreign key (inventory_item_id) references inventory_items(id) on delete cascade;
alter table game_clock add foreign key (session_id) references sessions(id) on delete cascade;
alter table time_log add foreign key (session_id) references sessions(id) on delete cascade;
alter table journal_entries add foreign key (session_id) references sessions(id) on delete set null;
alter table character_known_recipes add foreign key (journal_id) references journal_entries(id) on delete set null;
alter table roll_attempts add foreign key (request_id) references roll_requests(id) on delete cascade;
alter table skill_progress add foreign key (roll_request_id) references roll_requests(id) on delete set null;
alter table party_position add foreign key (campaign_run_id) references campaign_runs(id) on delete cascade;
alter table party_situation add foreign key (campaign_run_id) references campaign_runs(id) on delete cascade;
alter table walk_world add foreign key (campaign_run_id) references campaign_runs(id) on delete cascade;
alter table vtt_tokens add foreign key (map_id) references vtt_maps(id) on delete cascade;
alter table combat_state add foreign key (map_id) references vtt_maps(id) on delete cascade;
alter table npc_encounters add foreign key (character_id) references characters(id) on delete cascade;

-- the live triggers that would fight a restore (stand-ins that refuse loudly)
create function refuse() returns trigger language plpgsql as $$ begin raise exception 'trigger % fired during restore', tg_name; end $$;
create trigger character_lock_guard before update on characters for each row execute function refuse();
create trigger characters_history_aud after update on characters for each row execute function refuse();
create trigger time_log_apply before insert on time_log for each row execute function refuse();
create trigger vtt_tokens_no_stack before update or insert on vtt_tokens for each row execute function refuse();
create trigger travel_nodes_guard_waypoints before update on travel_nodes for each row execute function refuse();
create trigger npc_encounter_guard_trg before insert on npc_encounters for each row execute function refuse();
create role anon; create role authenticated; create role service_role;
